// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }
    function testFuzz_property(address caller, address newOwner) public {
        vm.assume(caller != newOwner);
        vm.prank(c.owner());
        c.transferOwnership(caller);
        vm.prank(caller);
        c.transferOwnership(newOwner);
        assertTrue(c.owner() == newOwner);
    }
}
